import { useMemo, useState } from 'react';
import '@gener8v/ui/styles.css';

const TOTAL = 2300;
const PAGE_SIZE = 25;
const PAGES = Math.ceil(TOTAL / PAGE_SIZE);

type Status = 'Paid' | 'Open' | 'Overdue';
const STATUSES: Status[] = ['Paid', 'Open', 'Overdue'];
const TAG: Record<Status, string> = {
  Paid: 'tag-success',
  Open: 'tag-neutral',
  Overdue: 'tag-danger',
};
const CUSTOMERS = ['Acme Corp', 'Northwind', 'Globex', 'Initech', 'Umbrella Ltd', 'Hooli', 'Stark Industries'];

const invoices = Array.from({ length: TOTAL }, (_, i) => ({
  id: `INV-${String(i + 1).padStart(5, '0')}`,
  customer: CUSTOMERS[(i * 7) % CUSTOMERS.length],
  issued: new Date(Date.UTC(2026, 0, 1 + i)).toISOString().slice(0, 10),
  amount: 120 + ((i * 7919) % 48000) / 10,
  status: STATUSES[(i * 5) % 3],
}));

const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });

function pageItems(current: number): (number | 'gap-l' | 'gap-r')[] {
  const set = new Set([1, PAGES, current - 1, current, current + 1]);
  const nums = [...set].filter((n) => n >= 1 && n <= PAGES).sort((a, b) => a - b);
  const out: (number | 'gap-l' | 'gap-r')[] = [];
  nums.forEach((n, i) => {
    if (i > 0 && n - nums[i - 1] > 1) out.push(i === 1 ? 'gap-l' : 'gap-r');
    out.push(n);
  });
  return out;
}

export function App() {
  const [page, setPage] = useState(1);
  const start = (page - 1) * PAGE_SIZE;
  const rows = invoices.slice(start, start + PAGE_SIZE);
  const items = useMemo(() => pageItems(page), [page]);

  return (
    <main className="container section stack">
      <h1>Invoices</h1>

      <div className="table-wrap">
        <table className="table">
          <caption className="muted">Invoices, page {page} of {PAGES}</caption>
          <thead>
            <tr>
              <th scope="col">Invoice</th>
              <th scope="col">Customer</th>
              <th scope="col">Issued</th>
              <th scope="col" className="num">Amount</th>
              <th scope="col">Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id}>
                <td className="mono">{r.id}</td>
                <td>{r.customer}</td>
                <td className="num">{r.issued}</td>
                <td className="num">{fmt.format(r.amount)}</td>
                <td><span className={`tag ${TAG[r.status]}`}>{r.status}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="table-pager">
        <p className="table-pager-range muted" aria-live="polite">
          {start + 1}–{start + rows.length} of {TOTAL.toLocaleString('en-US')}
        </p>
        <nav className="pagination" aria-label="Invoice pages">
          <button
            type="button"
            className="pagination-item"
            disabled={page === 1}
            onClick={() => setPage(page - 1)}
          >
            Previous
          </button>
          {items.map((it) =>
            typeof it === 'string' ? (
              <span key={it} className="pagination-gap" aria-hidden="true">…</span>
            ) : (
              <button
                key={it}
                type="button"
                className="pagination-item"
                aria-current={it === page ? 'page' : undefined}
                aria-label={`Page ${it}`}
                onClick={() => setPage(it)}
              >
                {it}
              </button>
            ),
          )}
          <button
            type="button"
            className="pagination-item"
            disabled={page === PAGES}
            onClick={() => setPage(page + 1)}
          >
            Next
          </button>
        </nav>
      </div>
    </main>
  );
}
